function clientToSvg(evt, svgEl, pan = { x: 0, y: 0 }, zoom = 1) {
  const pt = svgEl.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  const ctm = svgEl.getScreenCTM();
  const ipt = pt.matrixTransform(ctm.inverse());
  // 🔹 Pan / Zoom 반영 (좌표계 보정)
  return {
    x: (ipt.x - pan.x) / zoom,
    y: (ipt.y - pan.y) / zoom,
  };
}